<script setup lang="ts">
import { onMounted, ref } from 'vue'
import PageHeader from '../../components/common/PageHeader.vue'
import { request } from '../../api/http'
import { residentsApi, type ResidentSummary } from '../../api/residents'
const caregivers=ref<{id:string;name:string;phone_hint:string;resident_count:number}[]>([])
const rows=ref<ResidentSummary[]>([]), total=ref(0), page=ref(1), q=ref(''), busy=ref(false), loading=ref(false), error=ref(''), notice=ref('')
const selected=ref<{id:string;name:string;version:number}|null>(null), ids=ref<string[]>([]), reason=ref('')
async function load(){loading.value=true;error.value='';try{const [staff,result]=await Promise.all([request<typeof caregivers.value>('/auth/caregivers'),residentsApi.list(q.value,'',page.value)]);caregivers.value=staff;rows.value=result.items;total.value=result.total}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function choose(row:ResidentSummary){if(busy.value)return;busy.value=true;error.value='';notice.value='';selected.value=null;try{const detail=await residentsApi.detail(row.id);selected.value=detail;ids.value=[...detail.assigned_account_ids];reason.value=''}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}}
async function save(){if(!selected.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{await request(`/residents/${selected.value.id}/assignments`,{method:'PUT',body:JSON.stringify({version:selected.value.version,account_ids:ids.value,reason:reason.value.trim()})});selected.value=null;notice.value='负责关系已保存，护工下次访问档案时立即按新范围检查权限。';await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
function turn(next:number){page.value=next;void load()}
onMounted(load)
</script>
<template><div class="page residents"><PageHeader title="护工账号与分配" subtitle="护理部维护护工负责关系，护工按分配范围执行照护。"/>
<p v-if="error" class="resident-error" role="alert">{{ error }}</p><p v-if="notice" class="resident-notice" role="status">{{ notice }}</p>
<section class="card resident-section"><h2>护工账号</h2><p class="resident-helper">护工先申请岗位，由院长审核开通。原工作人员账号继续使用，无需重新注册；未分配老人时无法查看任何老人档案。</p><p v-if="loading" role="status">正在加载…</p><p v-else-if="!caregivers.length">暂无护工账号，请先注册。</p><div class="caregiver-grid"><article v-for="person in caregivers" :key="person.id" class="caregiver-card"><b>{{ person.name }}</b><span>{{ person.phone_hint }}</span><span>负责 {{ person.resident_count }} 位老人</span></article></div></section>
<section class="card resident-section"><h2>分配负责老人</h2><form class="assignment-search" @submit.prevent="turn(1)"><label for="assignment-query">老人姓名、档案号或房间<input id="assignment-query" v-model="q" class="input" maxlength="100"></label><button class="btn" :disabled="loading||busy">查询</button></form><div class="assignment-rows"><div v-for="row in rows" :key="row.id" class="assignment-row"><div><b>{{ row.name }}</b><p>{{ row.record_no }} · {{ row.location || '位置未登记' }} · {{ row.status==='in_care'?'在院':'已离院' }}</p></div><button class="btn" :disabled="busy||loading" @click="choose(row)">设置负责护工</button></div></div><p v-if="!loading&&!rows.length">没有匹配的老人档案。</p><div class="assignment-pager"><button class="btn" :disabled="page<=1||loading||busy" @click="turn(page-1)">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 人</span><button class="btn" :disabled="page*20>=total||loading||busy" @click="turn(page+1)">下一页</button></div></section>
<form v-if="selected" class="card resident-section" @submit.prevent="save"><h2>{{ selected.name }} · 负责护工</h2><p class="resident-helper">可由多位护工共同负责。取消全部勾选将收回所有护工的访问权限；护理部负责维护分配关系。</p><fieldset class="resident-fieldset" :disabled="busy"><div class="resident-assignees"><label v-for="person in caregivers" :key="person.id"><input v-model="ids" type="checkbox" :value="person.id"><span>{{ person.name }}<small>{{ person.phone_hint }}</small></span></label></div><label for="assignment-reason">分配或调整原因<input id="assignment-reason" v-model="reason" class="input" required maxlength="300"></label><div class="assignment-pager"><button class="btn primary" :disabled="!reason.trim()">{{ busy?'正在保存…':'保存负责关系' }}</button><button type="button" class="btn" @click="selected=null">取消</button></div></fieldset></form>
</div></template>
<style src="../../styles/residents.css"></style>
<style scoped>
.caregiver-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.caregiver-card{display:grid;gap:8px;border:1px solid var(--border,#e2e8f0);border-radius:12px;padding:16px}.caregiver-card span,.assignment-row p{color:var(--muted,#64748b)}.assignment-search,.assignment-pager,.assignment-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.assignment-search label{flex:1;min-width:180px;display:grid;gap:8px}.assignment-row{justify-content:space-between;padding:16px 0;border-bottom:1px solid var(--border,#e2e8f0)}.assignment-pager{margin-top:20px}.btn{min-height:44px}.assignment-row p{margin:6px 0}
</style>
